BASE=Path(__file__).resolve().parents[1];OUT=BASE/'.cache/batch200/drafts/rewrite_spec'
M=[['拉丁 mare → marīnus','海 → 海的、与海有关的']]
BR=M+[['古法语 marin → 法语 mariner','海的 → 用盐水腌制']]
W=[
E('marine','/məˈriːn/','海洋的；海生的；海军陆战队员','形容词把视线带到海里；作人的名称时，指海军陆战队员。','形容词经法语 marin，并有拉丁 marīnus 的直接影响，远接 mare“海”。人的名词义与从事海上军事任务的部队有关，不是普通水手的统称。',M+[['法语 marin / marine → 英语 marine','与海有关的；海上军事相关名称'],['英语 marine 的现代用法','海洋的；一名海军陆战队员']],'marine life 是海洋生物，marine pollution 是海洋污染。a marine 是一名海军陆战队员；特指美国等部队成员时常写 Marine。名词复数 marines 说人，不能用来泛称海里的动物。','marine life；marine biology；marine pollution；a former marine。','maritime 更常涉及航运、海事和沿海事务；marine 很常涉及海中生物与环境。两者有重叠。',('Plastic waste can harm marine life.','塑料垃圾可能伤害海洋生物。'),('He served as a marine before becoming a teacher.','他当教师前曾是海军陆战队员。'),sources=['https://www.etymonline.com/word/marine','https://dictionary.cambridge.org/dictionary/english/marine']),
E('maritime','英 /ˈmærɪtaɪm/；美 /ˈmærətaɪm/','海事的；航海的；沿海的','把海看成航线、贸易通道，以及影响岸上生活的环境。','经法语 maritime 或直接接拉丁 maritimus“海的、近海的”，词根是 mare。末尾不是英语 time，不能拆成“海的时间”。',[['拉丁 mare → maritimus','海 → 海的、靠海的'],['法语 maritime 或拉丁直接借入 → 英语 maritime','与航海、海事及沿海地区有关的']],'maritime trade 是海上贸易，maritime history 是航海或海事历史；maritime climate 指受海洋影响的气候。通常作名词前的形容词，语气比 sea 更正式。','maritime trade；maritime history；maritime climate；maritime safety。','naval 主要涉及海军；maritime 可以说民用航运、海上贸易和沿海环境。',('The city grew wealthy through maritime trade.','这座城市通过海上贸易富裕起来。'),('The museum explores the region’s maritime history.','博物馆介绍这个地区的航海历史。'),sources=['https://www.etymonline.com/word/maritime','https://dictionary.cambridge.org/dictionary/english/maritime']),
E('marina','英 /məˈriːnə/；美 /məˈriːnə/','游艇码头；小型船艇停泊港','一排排小船和游艇有固定泊位，还能得到相关服务的地方。','经西班牙语或意大利语 marina“海岸”借入，接拉丁 marīnus。英语先有海滨相关义，后来发展出供游艇、小船停靠的专门港区义。',M+[['西班牙语或意大利语 marina','海岸、海滨'],['英语 marina','海滨场所 → 供游艇、小型船艇停泊的港区']],'marina 通常让人想到休闲船只的泊位、栈桥和服务设施。虽然词源是海，如今湖边、河边也可以有 marina，并不必须通向大海。','at the marina；a berth in the marina；a lakeside marina。','harbour 是更宽的避风、停船水域；marina 特别偏向小型船艇和游艇的停泊设施。',('We rented a small boat at the marina.','我们在游艇码头租了一条小船。'),('The lakeside marina has space for eighty boats.','湖边的船艇码头可容纳八十条船。'),sources=['https://www.etymonline.com/word/marina','https://dictionary.cambridge.org/dictionary/english/marina']),
E('mariner','英 /ˈmærɪnə/；美 /ˈmærɪnər/','海员；水手；航海者','长期在海上航行、懂得船与海的人。','经盎格鲁法语 mariner、古法语 marinier，接中世纪拉丁 marinarius，再接 marīnus“海的”。看上去像 marine + -er，但英语是借入已有的从业者名称。',M+[['中世纪拉丁 marinarius → 古法语 marinier / 盎格鲁法语 mariner','航海者、水手'],['中古英语及英语 mariner','海员、航海者']],'常见于历史、文学和正式航海语境，如 experienced mariners。现代日常谈一个水手更常用 sailor；mariner 听起来更有航海经历或专业身份的味道。','an experienced mariner；merchant mariners；ancient mariners。','marine 作人名词指海军陆战队员；mariner 才是航海者、水手，两者不要只看相似拼写就互换。',('Experienced mariners watched the changing weather closely.','经验丰富的海员密切留意天气变化。'),('The book tells the story of a young mariner’s first voyage.','这本书讲述一个年轻海员第一次远航的故事。'),sources=['https://www.etymonline.com/word/mariner']),
E('marinade','英 /ˌmærɪˈneɪd/；美 /ˌmærəˈneɪd/','腌料；腌汁；用腌料浸泡','先把食材泡在调好味的液体里，让它带上味道。','借自法语 marinade，接 mariner“用盐水腌制”，再回到 marin“海的”。连接点是海水、盐水，不是食材必须来自海里。',BR+[['法语 marinade → 英语 marinade','腌制用的盐水、调味液；也用作腌制的动词']],'名词是那份腌料，常由油、醋、香草等搭配而成；不一定含海水，也不限鱼类。marinade 也能作动词，但写作时用 marinade 指料、marinate 指动作，容易分清。','a marinade for；in a marinade；a lemon marinade。','sauce 常随菜上桌或用于烹调；marinade 特别强调先浸泡食材的用途。同一种配方可能有不同用法。',('She mixed lemon juice and herbs to make a marinade.','她把柠檬汁和香草混合成腌料。'),('The tofu soaked up the flavour of the marinade.','豆腐吸收了腌料的味道。'),sources=['https://www.etymonline.com/word/marinade']),
E('marinate','英 /ˈmærɪneɪt/；美 /ˈmærəneɪt/','腌制；浸在腌料中','给味道一点时间，让调料慢慢进入食材。','英语调整了法语 mariner 或意大利语 marinare 的词形；二者与海水、盐水的命名相关。不是现代英语先有 marinade，再简单把 -ade 换成 -ate。',M+[['法语 mariner 或意大利语 marinare','用盐水或调味液腌制'],['英语 marinate','把食材浸在腌料里；食材在腌料中入味']],'可以说 marinate the chicken，食材作宾语；也可以说 leave it to marinate，食材自己浸着入味。口语里 let an idea marinate 还比喻先让想法沉淀一下。','marinate in；leave to marinate；marinated vegetables。','marinade 常指腌料，marinate 常指腌制动作。注意主重音：marinade 在末尾，marinate 在开头。',('She marinated the mushrooms in olive oil and herbs.','她用橄榄油和香草腌蘑菇。'),('Let the idea marinate before we make a decision.','先让这个想法沉淀一下，我们再决定。'),sources=['https://www.etymonline.com/word/marinate','https://en.wiktionary.org/wiki/marinate#English']),
E('marinara','英 /ˌmærɪˈnɑːrə/；美 /ˌmærəˈnɑːrə/，也读 /ˌmerəˈnerə/','意式番茄酱；配这种酱的','菜单上常见的蒜香番茄酱名字，不要看到“海”就自动找海鲜。','来自意大利语 alla marinara“水手风格的”，其中 marinara 联系 marinaio“水手”、marino“海的”，远接拉丁 marīnus。',M+[['意大利语 alla marinara','按水手风格制作'],['英语 marinara','常指一种意式番茄酱，或配这种酱的菜']],'在美国菜单中通常指番茄、蒜和香草等做的酱，未必有海鲜。部分地区的菜名 marinara 会用于海鲜做法，所以点菜时仍要看菜单说明。','marinara sauce；pasta with marinara；a jar of marinara。','marinade 是浸泡食材的腌料；marinara 是具体的意式酱或菜式名称。相似拼写不等于同一种酱。',('We served the pasta with a simple marinara sauce.','我们给意面配了简单的意式番茄酱。'),('The menu describes its marinara as a tomato and garlic sauce.','菜单说明这里的 marinara 是番茄蒜酱。'),sources=['https://www.merriam-webster.com/dictionary/marinara','https://www.etymonline.com/word/marinara']),
E('ultramarine','/ˌʌltrəməˈriːn/','群青；群青色的','一种浓而鲜明的蓝，名字却说的是“海那边来的”。','来自中世纪拉丁 ultramarinus，由 ultra“在……之外” + marīnus“海的”组成。颜料原料青金石从海外运入欧洲，因此得名；不是因为它比海水更蓝。',M+[['中世纪拉丁 ultramarinus','海那边的、海外的'],['英语 ultramarine','由海外青金石制得的蓝色颜料 → 群青色']],'既可以说颜料，也可以说颜色。早期天然群青来自青金石，如今也有合成群青；词里保留的是历史贸易路线，不是要求每一管颜料都由海外宝石研成。','ultramarine blue；ultramarine pigment；a tube of ultramarine。','navy blue 通常更深暗；ultramarine 是鲜明的群青蓝。颜色边界会随颜料和用法有所差异。',('The painter used ultramarine for the evening sky.','画家用群青画傍晚的天空。'),('An ultramarine scarf added colour to her grey coat.','一条群青色围巾给她的灰外套添了色彩。'),sources=['https://www.etymonline.com/word/ultramarine','https://en.wiktionary.org/wiki/ultramarine#English']),
E('aquamarine','英 /ˌækwəməˈriːn/；美 /ˌɑːkwəməˈriːn/','海蓝宝石；浅蓝绿色；浅蓝绿色的','像清浅海水那样，蓝里带一点绿。','经法语或普罗旺斯语借入，源自拉丁 aqua marina“海水”：aqua 是水，marina 是“海的”这一形容词的阴性形式。先用于宝石，后用于颜色。',M+[['拉丁 aqua marina','海水'],['法语或普罗旺斯语的宝石名称 → 英语 aquamarine','蓝绿色的绿柱石宝石 → 浅蓝绿色']],'可以是戒指上的海蓝宝石，也可以直接修饰衣服、墙面等的颜色。宝石名和颜色名来自海水的视觉联想，不是说宝石长在海里。','an aquamarine ring；aquamarine blue；an aquamarine dress。','ultramarine 更偏鲜明浓蓝；aquamarine 常偏清浅的蓝绿色。两词的海洋联系一个是来源地，一个是颜色联想。',('The ring was set with a pale aquamarine.','戒指上镶着一颗浅色海蓝宝石。'),('She chose aquamarine tiles for the bathroom.','她为浴室挑了浅蓝绿色瓷砖。'),sources=['https://www.etymonline.com/word/aquamarine','https://dictionary.cambridge.org/dictionary/english/aquamarine'])
]
m=json.loads((BASE/'.cache/batch200/rewrite_spec.json').read_text());family=next(r['family'] for r in m['roots'] if r['id']=='C0708')
shared={'submarine','submariner'}
excluded={k:'按用户最新选词范围暂略：较专门的地貌、养殖术语或低频过程名词，先保留通用阅读与生活词。' for k in 'maar mariculture marination'.split()}
ROOT=[dict(id='C0708',meaning='海；海洋',core='mar- = sea：海里、海上、海岸，以及海水带来的联想。',image='marine life 在海里，maritime trade 走海上航线，marina 是小船停靠的港区；腌料则通过“海水 → 盐水”接到这条词根。',intro='来自拉丁 mare“海”及 marīnus“海的”。许多词经法语、意大利语或其他罗曼语进入英语。ultramarine 的海是原料运来的海外，aquamarine 的海是蓝绿色海水的样子，不能只用一个“海蓝”解释所有颜色词。',forms='marine、maritime 是不同拉丁形容词的后代。mariner 经法语借入；marinate 与 marinade 的重音和常用词性不同，不是看见相同开头就能互换。',branches=[['海洋、航运与人','marine、maritime、mariner、submarine、submariner'],['停泊地点','marina'],['食物与调味','marinade、marinate、marinara'],['颜料、宝石与颜色','ultramarine、aquamarine']],contrasts='marine 作人名词是海军陆战队员，mariner 是海员。marinara 不一定有海鲜；marinade 的历史连接点是盐水。英语 mare“母马”与拉丁 mare“海”只是碰巧同形。',practice='用 marine life、maritime trade 和 marina 各说一句话；再解释腌料与海的关系，以及两个蓝色词为什么命名不同。',words=[k for k in family if k not in excluded],exclude=excluded,sources=['https://www.etymonline.com/word/marine','https://www.etymonline.com/word/marinade'])]
assert {x['word'] for x in W}==set(family)-shared-set(excluded)
assert len(W)==len({x['word'] for x in W})
assert all(x['word'] in m['owned_words'] for x in W)
for x in W:
 assert len(x['examples'])>=2 and len(x['history'])>=2 and x['ipa'],x['word']
 assert all(len(n)==2 and all(isinstance(v,str) and v for v in n) for n in x['history']),x['word']
for k,d in [('roots',ROOT),('words',W)]: (OUT/f'{k}_batch200_spec_58_mar.json').write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
